import type { QAProps } from "../types.js";
export type ProgressTheme = 'default' | 'success' | 'warning' | 'danger' | 'info' | 'misc';
export type ProgressSize = 'xs' | 's' | 'm';
export type ProgressValue = number;
export interface Stack {
    value: ProgressValue;
